const state = $getWorkflowStaticData('global');
state.positions = {};
console.log('Estado reseteado completamente');
return [{ json: { ok: true, message: 'Estado limpiado', positions: {} } }];

const API_KEY    = process.env.BINANCE_API_KEY;
const API_SECRET = process.env.BINANCE_API_SECRET;
const BASE       = 'https://fapi.binance.com';
const DASHBOARD  = process.env.INTERNAL_DASHBOARD_BASE || 'http://127.0.0.1:3001';
const crypto     = require('crypto');
const state      = $getWorkflowStaticData('global');
const EXECUTION_ENGINE = process.env.EXECUTION_ENGINE_URL || 'http://position_guard:3091/executions';
const EXECUTION_TOKEN  = process.env.EXECUTION_ENGINE_TOKEN;

async function executeVerified(helpers, request){
  const executionId = crypto.randomUUID();
  if(!EXECUTION_TOKEN){
    return { ok:false, executionId, finalStatus:'FAILED', error:'EXECUTION_ENGINE_TOKEN is not configured' };
  }
  try{
    const result = await helpers.httpRequest({
      method:'POST', url:EXECUTION_ENGINE, json:true, timeout:180000,
      headers:{ Authorization:`Bearer ${EXECUTION_TOKEN}` },
      body:{ ...request, executionId, maxAttempts:3 }
    });
    if(result?.ok === true && result.finalStatus === 'VERIFIED' && result.verificationResult?.verified === true){
      return result;
    }
    return { ...result, ok:false, executionId:result?.executionId || executionId,
      finalStatus:result?.finalStatus || 'FAILED', error:result?.error || 'Binance verification failed' };
  }catch(error){
    return { ok:false, executionId, finalStatus:'FAILED', error:error.message, failureNotificationSent:false };
  }
}

function executionFailureText(result, action, symbol){
  if(result?.failureNotificationSent) return null;
  return [
    '🚨 ATERUM EXECUTION FAILED',
    `${action} ${symbol}`,
    `Execution ID: ${result?.executionId || 'not-created'}`,
    result?.verificationResult?.exchangeVerified
      ? 'Binance confirmed the exchange action, but local persistence/synchronization failed.'
      : 'Binance did not confirm the requested change. Local trade state was not advanced.',
    'No success notification was sent.',
    `Error: ${String(result?.error || 'unknown').slice(0,500)}`
  ].join('\n');
}

if(!state.positions || Object.keys(state.positions).length === 0){
  return [{ json: { status: 'no_positions_active' } }];
}

function sign(params){
  const query = Object.entries({ ...params, timestamp: Date.now(), recvWindow: 60000 })
    .map(([k,v]) => `${k}=${encodeURIComponent(v)}`).join('&');
  return query + '&signature=' + crypto.createHmac('sha256', API_SECRET).update(query).digest('hex');
}

function matchesTrackedPosition(p, symbol, trackedSide){
  if(!p || p.symbol !== symbol) return false;
  const amt = parseFloat(p.positionAmt || 0);
  if(!Number.isFinite(amt) || Math.abs(amt) <= 0) return false;
  const inferredSide = amt > 0 ? 'LONG' : 'SHORT';
  if(p.positionSide === trackedSide) return true; // hedge mode
  if((p.positionSide === 'BOTH' || !p.positionSide) && inferredSide === trackedSide) return true; // one-way mode
  return false;
}

function buildCloseOrderParams(symbol, side, qty, trackedSide, activePos){
  const params = { symbol, side, type:'MARKET', quantity:qty };
  // En hedge mode debemos enviar positionSide, en one-way NO.
  if(activePos && activePos.positionSide && activePos.positionSide !== 'BOTH'){
    params.positionSide = trackedSide;
  }
  return params;
}

function esc(v){ return String(v||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

function buildLearningContext(pos){
  const ind = pos.indicators || {};
  const tf = pos.tf4h || {};
  const mc = pos.marketContext || {};
  return {
    positionSide: pos.positionSide || null,
    entryPrice: pos.entryPrice || null,
    initialSL: pos.initialSL || null,
    tp: pos.tp || null,
    leverage: pos.leverage || null,
    finalScore: pos.finalScore || null,
    scanScore: pos.scanScore || null,
    dynamicThreshold: pos.dynamicThreshold || null,
    aiRegime: pos.aiRegime || null,
    aiBias: pos.aiBias || null,
    tf4hStatus: tf.status || null,
    macroBias: mc.market_bias || null,
    atrPct: ind.atrPct || null,
    rsi14: ind.rsi14 || null,
    volRatio: ind.volRatio || null,
    fundingRate: ind.fundingRate || null,
    setupLabel: pos.setupLabel || null,
    entryReason: pos.entryReason || pos.aiReasoning || null
  };
}

function buildCloseMessage(symbol, pos, exitPrice, reason, pnl, rFinal, durationMinutes, extraNote=''){
  const dir     = pos.positionSide === 'SHORT' ? '🔴 SHORT' : '🟢 LONG';
  const ts      = new Date().toISOString().replace('T',' ').slice(0,19) + ' UTC';
  const durTxt  = durationMinutes < 60
    ? `${durationMinutes}m`
    : `${Math.floor(durationMinutes/60)}h ${durationMinutes%60}m`;
  const pnlSign = pnl >= 0 ? '+' : '';
  const pnlPct  = pos.entryPrice > 0
    ? ((pnl / (pos.entryPrice * pos.qty)) * 100).toFixed(2)
    : '0.00';
  const reasonMap = {
    TP:       { emoji:'🎯', label:'Take Profit Alcanzado',     color:'✅' },
    SL:       { emoji:'🛑', label:'Stop Loss Ejecutado',       color:'❌' },
    TIME_EXIT:{ emoji:'⏱', label:'Cierre por Tiempo (20h)',   color:'⚠️' },
  };
  const r = reasonMap[reason] || { emoji:'⚪', label:reason, color:'—' };
  const stageMap = {
    INITIAL:'Initial', BREAKEVEN:'Breakeven ⚖',
    TIME_LOCK:'Time Lock ⏰', LOCK:'Lock 🔒', TRAILING:'Trailing 🎯'
  };
  const stage    = pos.stage || 'INITIAL';
  const pnlEmoji = pnl >= 0 ? '💚' : '🔴';

  return [
    '━━━━━━━━━━━━━━━━━━━━━━━',
    `${r.emoji} TRADE CERRADO — ${r.color} ${r.label}`,
    extraNote ? `   ${extraNote}` : null,
    '━━━━━━━━━━━━━━━━━━━━━━━',
    '',
    `${dir}   💎 ${esc(symbol)}`,
    `⏰ ${ts}`,
    '',
    '─── RESULTADO ───',
    `  ${pnlEmoji} PnL      : ${pnlSign}$${Math.abs(pnl).toFixed(2)}   (${pnlSign}${pnlPct}%)`,
    `  R final  : ${rFinal >= 0 ? '+' : ''}${rFinal}R`,
    `  Duración : ${durTxt}`,
    `  Stage    : ${stageMap[stage] || stage}`,
    '',
    '─── PRECIOS ───',
    `  Entry    : $${esc(pos.entryPrice)}`,
    `  Exit     : $${esc(exitPrice)}`,
    `  SL era   : $${esc(pos.slPrice)}`,
    `  TP era   : $${esc(pos.tp || 'N/A')}`,
    '',
    '─── POSICION ───',
    `  Qty      : ${esc(pos.qty)}`,
    `  Leverage : ${esc(pos.leverage || '—')}x`,
    `  SL ini   : $${esc(pos.initialSL || pos.slPrice)}`,
    `  Score AI : ${esc(pos.finalScore || '—')}/100`,
    '━━━━━━━━━━━━━━━━━━━━━━━'
  ].filter(l => l !== null).join('\n');
}

async function closeDashboard(symbol, reason, price){
  await this.helpers.httpRequest({
    method: 'DELETE',
    url: `${DASHBOARD}/trade/${symbol}?reason=${reason}&exitPrice=${price}`,
    json: true
  });
  console.log(`Dashboard: ${symbol} cerrado (${reason}) @ ${price}`);
}

async function closeDB(symbol, pos, exitPrice, reason){
  try{
    const pnl = pos.positionSide === 'SHORT'
      ? (pos.entryPrice - exitPrice) * pos.qty
      : (exitPrice - pos.entryPrice) * pos.qty;
    const initialSL   = pos.initialSL || pos.slPrice;
    const initialRisk = Math.abs(pos.entryPrice - initialSL);
    const rFinal = initialRisk > 0
      ? +((Math.abs(exitPrice - pos.entryPrice) / initialRisk) * (pnl >= 0 ? 1 : -1)).toFixed(2)
      : 0;
    const durationMinutes = pos.openedAt
      ? Math.floor((Date.now() - pos.openedAt) / 60000)
      : null;
    await this.helpers.httpRequest({
      method: 'POST', url: `${DASHBOARD}/db/trade/close`, json: true,
      body: {
        symbol, exitPrice,
        pnlUsdt:        +pnl.toFixed(2),
        pnlPct:         +((pnl / (pos.entryPrice * pos.qty)) * 100).toFixed(3),
        rFinal,
        closeReason:    reason,
        trailingStage:  pos.stage || 'INITIAL',
        durationMinutes
      }
    });
    console.log(`DB: trade cerrado ${symbol} pnl=${pnl.toFixed(2)} reason=${reason}`);
    return { pnl: +pnl.toFixed(2), rFinal, durationMinutes };
  }catch(e){
    console.log(`DB close error ${symbol}: ${e.message}`);
    throw e;
  }
}

async function readConfirmedExit(helpers, symbol, pos){
  const startTime=Math.max(0, Number(pos.openedAt||Date.now())-60000);
  const trades=await helpers.httpRequest({
    method:'GET', url:`${BASE}/fapi/v1/userTrades?${sign({symbol,startTime,limit:1000})}`,
    headers:{'X-MBX-APIKEY':API_KEY}, json:true
  });
  const closingSide=pos.positionSide==='LONG'?'SELL':'BUY';
  const fills=(Array.isArray(trades)?trades:[]).filter(t=>t.side===closingSide && Number(t.time||0)>=startTime);
  if(!fills.length) throw new Error('Binance position is closed but no closing fill could be verified');
  const latestTime=Math.max(...fills.map(t=>Number(t.time||0)));
  const latest=fills.filter(t=>Math.abs(Number(t.time||0)-latestTime)<2000);
  const qty=latest.reduce((sum,t)=>sum+Number(t.qty||0),0);
  const exitPrice=latest.reduce((sum,t)=>sum+Number(t.price||0)*Number(t.qty||0),0)/(qty||1);
  const realizedPnl=latest.reduce((sum,t)=>sum+Number(t.realizedPnl||0),0);
  const orderId=String(latest[0].orderId||'');
  const [orders,algos]=await Promise.all([
    helpers.httpRequest({method:'GET',url:`${BASE}/fapi/v1/allOrders?${sign({symbol,startTime,limit:1000})}`,headers:{'X-MBX-APIKEY':API_KEY},json:true}).catch(()=>[]),
    helpers.httpRequest({method:'GET',url:`${BASE}/fapi/v1/allAlgoOrders?${sign({symbol,startTime,limit:1000})}`,headers:{'X-MBX-APIKEY':API_KEY},json:true}).catch(()=>[])
  ]);
  const order=[...(orders||[]),...(algos||[])].find(o=>String(o.orderId||o.actualOrderId||o.algoId||'')===orderId);
  const type=String(order?.origType||order?.type||order?.orderType||'').toUpperCase();
  const reason=type.includes('STOP')?'SL':type.includes('TAKE_PROFIT')||type==='LIMIT'?'TP':'MANUAL';
  return { exitPrice,realizedPnl,orderId,reason,fills:latest,order:order||null,verified:true };
}
async function notifyCB(event, positionSide, symbol){
  try{
    await this.helpers.httpRequest({
      method: 'POST', url: `${DASHBOARD}/cb/${event}`, json: true,
      body: { direction: positionSide, symbol }
    });
    console.log(`[CB] ${event.toUpperCase()} notificado: ${symbol} ${positionSide}`);
  }catch(e){ console.log(`[CB] notify error: ${e.message}`); }
}

async function setCooldown(symbol, minutes){
  try{
    await this.helpers.httpRequest({
      method: 'POST', url: `${DASHBOARD}/cooldown/set`, json: true,
      body: { symbol, minutes }
    });
    console.log(`[Cooldown] ${symbol} pausado ${minutes}min tras cierre`);
  }catch(e){ console.log(`[Cooldown] set error ${symbol}: ${e.message}`); }
}

async function updateSLDashboard(symbol, newSL){
  try{
    await this.helpers.httpRequest({
      method: 'POST', url: `${DASHBOARD}/db/trade/update-sl`, json: true,
      body: { symbol, newSL }
    });
  }catch(e){ console.log(`[SL Update] DB error ${symbol}: ${e.message}`); }
}

// ── Gestión profesional de tiempo en pérdida ──────────────────────────────────
// Reglas moderadas:
// 6h  en pérdida sin tocar BE → mover SL 30% más cerca
// 12h en pérdida sin tocar BE → mover SL 50% más cerca
// 20h en pérdida sin tocar BE → cierre forzado
function calcTimeSLAdjustment(pos, currentPrice, hoursOpen){
  const stage = pos.stage || 'INITIAL';

  // Solo aplica en stage INITIAL — si ya movió a BE o mejor, no tocar
  if(stage !== 'INITIAL') return null;

  const isLong  = pos.positionSide === 'LONG';
  const entry   = pos.entryPrice;
  const slOrig  = pos.initialSL || pos.slPrice;
  const slDist  = Math.abs(entry - slOrig);

  // Verificar si está en pérdida ahora mismo
  const inLoss = isLong
    ? currentPrice < entry
    : currentPrice > entry;

  if(!inLoss) return null; // en ganancia → no aplicar

  // Verificar si alguna vez tocó ganancia (si sí, el trailing ya debería haber actuado)
  const bestPrice = pos.bestPrice || entry;
  const everInProfit = isLong
    ? bestPrice > entry * 1.001  // tocó al menos 0.1% de ganancia
    : bestPrice < entry * 0.999;

  if(everInProfit) return null; // ya tuvo profit → no aplicar estas reglas

  if(hoursOpen >= 20){
    return { action: 'FORCE_CLOSE', reason: 'TIME_EXIT', note: '20h en pérdida sin recuperación' };
  }

  if(hoursOpen >= 12){
    // Mover SL 50% más cerca del entry
    const newSLDist = slDist * 0.50;
    const newSL = isLong
      ? +(entry - newSLDist).toFixed(4)
      : +(entry + newSLDist).toFixed(4);

    // Solo mover si es más restrictivo que el SL actual
    const shouldMove = isLong
      ? newSL > pos.slPrice
      : newSL < pos.slPrice;

    if(shouldMove){
      return { action: 'MOVE_SL', newSL, note: `12h en pérdida → SL movido 50% más cerca ($${newSL})` };
    }
  }

  if(hoursOpen >= 6){
    // Mover SL 30% más cerca del entry
    const newSLDist = slDist * 0.70; // 70% de la distancia original = 30% más cerca
    const newSL = isLong
      ? +(entry - newSLDist).toFixed(4)
      : +(entry + newSLDist).toFixed(4);

    const shouldMove = isLong
      ? newSL > pos.slPrice
      : newSL < pos.slPrice;

    if(shouldMove){
      return { action: 'MOVE_SL', newSL, note: `6h en pérdida → SL movido 30% más cerca ($${newSL})` };
    }
  }

  return null;
}

const results = [];

for(const symbol of Object.keys(state.positions)){
  const pos = state.positions[symbol];
  const { positionSide, slPrice, qty, side } = pos;

  try{
    const posRisk = await this.helpers.httpRequest({
      method: 'GET',
      url: `${BASE}/fapi/v2/positionRisk?${sign({ symbol })}`,
      headers: { 'X-MBX-APIKEY': API_KEY },
      json: true
    });

    const arr       = Array.isArray(posRisk) ? posRisk : [posRisk];
    const activePos = arr.find(p => matchesTrackedPosition(p, symbol, positionSide));

    // Binance position is absent; verify the actual closing fill before local mutation.
    if(!activePos){
      try{
        const exit=await readConfirmedExit(this.helpers,symbol,pos);
        await closeDB.call(this,symbol,pos,exit.exitPrice,exit.reason);
        await closeDashboard.call(this,symbol,exit.reason.toLowerCase(),exit.exitPrice);
        const pnl=Number(exit.realizedPnl.toFixed(2));
        const initialRisk=Math.abs(pos.entryPrice-(pos.initialSL||pos.slPrice));
        const rFinal=initialRisk>0?+((Math.abs(exit.exitPrice-pos.entryPrice)/initialRisk)*(pnl>=0?1:-1)).toFixed(2):0;
        const durationMinutes=pos.openedAt?Math.floor((Date.now()-pos.openedAt)/60000):0;
        await notifyCB.call(this,exit.reason==='SL'?'sl':'tp',positionSide,symbol);
        await setCooldown.call(this,symbol,exit.reason==='SL'?15:30);
        const telegramText=buildCloseMessage(symbol,pos,exit.exitPrice,exit.reason,pnl,rFinal,durationMinutes);
        delete state.positions[symbol];
        results.push({symbol,status:'EXCHANGE_CLOSE_VERIFIED',exitPrice:exit.exitPrice,pnl,rFinal,durationMinutes,
          closeType:exit.reason,exchangeOrderId:exit.orderId,exchangeResponse:{fills:exit.fills,order:exit.order},
          verificationResult:{verified:true,position:null,fillVerified:true},finalStatus:'VERIFIED',telegramText,...buildLearningContext(pos)});
      }catch(error){
        results.push({symbol,status:'EXTERNAL_CLOSE_UNVERIFIED',finalStatus:'FAILED',message:error.message,
          telegramText:executionFailureText({error:error.message,failureNotificationSent:false},'VERIFY EXTERNAL CLOSE',symbol)});
      }
      continue;
    }

    // ── Precio actual ─────────────────────────────────────────────────────────
    const ticker = await this.helpers.httpRequest({
      method: 'GET', url: `${BASE}/fapi/v1/ticker/price?symbol=${symbol}`, json: true
    });
    const price = parseFloat(ticker.price);

    // ── Actualizar mejor precio visto ─────────────────────────────────────────
    const isLong = positionSide === 'LONG';
    if(!pos.bestPrice) pos.bestPrice = pos.entryPrice;
    if(isLong && price > pos.bestPrice)  pos.bestPrice = price;
    if(!isLong && price < pos.bestPrice) pos.bestPrice = price;

    // ── Calcular tiempo abierto ───────────────────────────────────────────────
    const hoursOpen = pos.openedAt
      ? (Date.now() - pos.openedAt) / 3600000
      : 0;

    const slTriggered = positionSide === 'SHORT' ? price >= slPrice : price <= slPrice;
    console.log(`${symbol} price=${price} sl=${slPrice} stage=${pos.stage||'INITIAL'} triggered=${slTriggered} hoursOpen=${hoursOpen.toFixed(1)}h`);

    if(slTriggered){
      const execution=await executeVerified(this.helpers,{
        type:'CLOSE_POSITION',symbol,positionSide,reason:'STOP_LOSS_TRIGGERED'
      });
      if(!execution.ok){
        results.push({symbol,status:'SL_EXECUTION_FAILED',finalStatus:execution.finalStatus,executionId:execution.executionId,
          message:execution.error,telegramText:executionFailureText(execution,'CLOSE POSITION (SL)',symbol)});
        continue;
      }
      const closeOrder=execution.exchangeResponse?.order||{};
      const exitPrice=Number(closeOrder.avgPrice||price);
      await closeDB.call(this,symbol,pos,exitPrice,'SL');
      await closeDashboard.call(this,symbol,'sl',exitPrice);
      const pnl=pos.positionSide==='SHORT'?(pos.entryPrice-exitPrice)*pos.qty:(exitPrice-pos.entryPrice)*pos.qty;
      const initialRisk=Math.abs(pos.entryPrice-(pos.initialSL||pos.slPrice));
      const rFinal=initialRisk>0?+((Math.abs(exitPrice-pos.entryPrice)/initialRisk)*(pnl>=0?1:-1)).toFixed(2):0;
      const durationMinutes=pos.openedAt?Math.floor((Date.now()-pos.openedAt)/60000):0;
      const stage=pos.stage||'INITIAL';
      const isRealLoss=stage==='INITIAL'&&pnl<0;
      await notifyCB.call(this,isRealLoss?'sl':'tp',positionSide,symbol);
      await setCooldown.call(this,symbol,isRealLoss?15:30);
      const telegramText=buildCloseMessage(symbol,pos,exitPrice,'SL',pnl,rFinal,durationMinutes);
      delete state.positions[symbol];
      results.push({symbol,status:'SL_EXECUTED',price:exitPrice,slPrice,stage,pnl:+pnl.toFixed(2),rFinal,durationMinutes,
        closeType:'SL',telegramText,executionId:execution.executionId,exchangeOrderId:execution.exchangeOrderId,
        exchangeResponse:execution.exchangeResponse,verificationResult:execution.verificationResult,
        timestamp:execution.timestamp,finalStatus:execution.finalStatus,...buildLearningContext(pos)});
    } else {

      // ── Gestión por tiempo en pérdida ─────────────────────────────────────
      const timeAction = calcTimeSLAdjustment(pos, price, hoursOpen);

      if(timeAction){

        if(timeAction.action === 'FORCE_CLOSE'){
          const execution=await executeVerified(this.helpers,{
            type:'CLOSE_POSITION',symbol,positionSide,reason:'TIME_EXIT_20H'
          });
          if(!execution.ok){
            results.push({symbol,status:'TIME_EXIT_FAILED',finalStatus:execution.finalStatus,executionId:execution.executionId,
              message:execution.error,telegramText:executionFailureText(execution,'CLOSE POSITION (TIME EXIT)',symbol)});
            continue;
          }
          const closeOrder=execution.exchangeResponse?.order||{};
          const exitPrice=Number(closeOrder.avgPrice||price);
          await closeDB.call(this,symbol,pos,exitPrice,'TIME_EXIT');
          await closeDashboard.call(this,symbol,'time_exit',exitPrice);
          const pnl=pos.positionSide==='SHORT'?(pos.entryPrice-exitPrice)*pos.qty:(exitPrice-pos.entryPrice)*pos.qty;
          const initialRisk=Math.abs(pos.entryPrice-(pos.initialSL||pos.slPrice));
          const rFinal=initialRisk>0?+((Math.abs(exitPrice-pos.entryPrice)/initialRisk)*(pnl>=0?1:-1)).toFixed(2):0;
          const durationMinutes=pos.openedAt?Math.floor((Date.now()-pos.openedAt)/60000):0;
          await notifyCB.call(this,'sl',positionSide,symbol);
          await setCooldown.call(this,symbol,60);
          const telegramText=buildCloseMessage(symbol,pos,exitPrice,'TIME_EXIT',pnl,rFinal,durationMinutes,`⏱ ${timeAction.note}`);
          delete state.positions[symbol];
          results.push({symbol,status:'TIME_EXIT',price:exitPrice,pnl:+pnl.toFixed(2),rFinal,durationMinutes,
            closeType:'TIME_EXIT',telegramText,executionId:execution.executionId,exchangeOrderId:execution.exchangeOrderId,
            exchangeResponse:execution.exchangeResponse,verificationResult:execution.verificationResult,
            timestamp:execution.timestamp,finalStatus:execution.finalStatus,...buildLearningContext(pos)});
        } else if(timeAction.action === 'MOVE_SL'){
          const execution=await executeVerified(this.helpers,{
            type:'MOVE_STOP_LOSS',symbol,positionSide,targetPrice:timeAction.newSL,reason:timeAction.note
          });
          if(!execution.ok){
            results.push({symbol,status:'TIME_SL_FAILED',finalStatus:execution.finalStatus,executionId:execution.executionId,
              message:execution.error,telegramText:executionFailureText(execution,'MOVE STOP LOSS (TIME)',symbol)});
            continue;
          }
          state.positions[symbol].slPrice=timeAction.newSL;
          state.positions[symbol].lastExecutionId=execution.executionId;
          await this.helpers.httpRequest({method:'POST',url:`${DASHBOARD}/trade`,json:true,body:{
            symbol,side:positionSide,entryPrice:pos.entryPrice,sl:timeAction.newSL,tp:pos.tp||0,
            qty:pos.qty,leverage:pos.leverage||1,openedAt:pos.openedAt,stage:pos.stage||'INITIAL',
            initialSL:pos.initialSL||pos.slPrice,aiResult:{regime:pos.aiRegime||'N/A',direction_bias:positionSide}
          }});
          results.push({
            symbol,status:'TIME_SL_ADJUSTED',price,oldSL:slPrice,newSL:timeAction.newSL,
            hoursOpen:+hoursOpen.toFixed(1),note:timeAction.note,
            executionId:execution.executionId,exchangeOrderId:execution.exchangeOrderId,
            exchangeResponse:execution.exchangeResponse,verificationResult:execution.verificationResult,
            timestamp:execution.timestamp,finalStatus:execution.finalStatus,
            telegramText:[
              '━━━━━━━━━━━━━━━━━━━━━━━','⏱ SL AJUSTADO POR TIEMPO','━━━━━━━━━━━━━━━━━━━━━━━',
              `💎 ${symbol}   ${isLong?'🟢 LONG':'🔴 SHORT'}`,'',
              `  ${timeAction.note}`,`  SL anterior : $${slPrice}`,`  SL nuevo    : $${timeAction.newSL}`,
              `  Precio act  : $${price}`,`  Entry       : $${pos.entryPrice}`,
              `  Tiempo      : ${Math.floor(hoursOpen)}h ${Math.round((hoursOpen%1)*60)}m`,'━━━━━━━━━━━━━━━━━━━━━━━'
            ].join('\n')
          });
        }

      } else {
        // ── Monitoreo normal ──────────────────────────────────────────────
        const diff = positionSide === 'SHORT'
          ? (slPrice - price).toFixed(4)
          : (price - slPrice).toFixed(4);
        results.push({
          symbol, status:'monitoring', price, slPrice,
          positionSide, stage: pos.stage||'INITIAL',
          entryPrice: pos.entryPrice||null, diff,
          hoursOpen: +hoursOpen.toFixed(1),
          telegramText: null
        });
      }
    }

  }catch(err){
    results.push({ symbol, status:'error', finalStatus:'FAILED', message:err.message,
      telegramText:executionFailureText({error:err.message,failureNotificationSent:false},'TRADE MANAGEMENT',symbol) });
  }
}

return results.map(r => ({ json: r }));

const ANTHROPIC_KEY = process.env.ANTHROPIC_API_KEY;
const DASHBOARD     = 'http://127.0.0.1:3001';

const t = $input.first().json;

// Only Binance-verified close events may produce post-trade notifications.
const verifiedClose=['SL_EXECUTED','TIME_EXIT','EXCHANGE_CLOSE_VERIFIED'].includes(t.status) && t.finalStatus==='VERIFIED';
if(!verifiedClose){ return []; }

const symbol    = t.symbol;
const pnl       = t.pnl || 0;
const rFinal    = t.rFinal || 0;
const stage     = t.stage || 'INITIAL';
const isLoss    = pnl < 0;
const closeType = t.closeType || ((t.status === 'SL_EXECUTED' || t.status === 'TIME_EXIT') ? 'SL' : 'TP');

// ── Obtener contexto del trade desde DB ───────────────────────────────────────
let tradeData = {};
try{
  const stats  = await this.helpers.httpRequest({ method:'GET', url:`${DASHBOARD}/db/stats`, json:true });
  const recent = stats.recent || [];
  const trade  = recent.find(r => r.symbol === symbol && r.status === 'CLOSED' && r.pnl_usdt != null);
  if(trade) tradeData = trade;
}catch(e){ console.log('DB context error:', e.message); }

const context = {
  tradeId: t.tradeId || t.id || tradeData.id || null,
  entryReason: t.entryReason || tradeData.entry_reason || null,
  exitReason: t.status || closeType,
  setupLabel: t.setupLabel || tradeData.setup_label || null,
  aiRegime: t.aiRegime || tradeData.ai_regime || null,
  aiBias: t.aiBias || tradeData.ai_bias || null,
  tf4hStatus: t.tf4hStatus || tradeData.tf4h_status || null,
  macroBias: t.macroBias || tradeData.macro_bias || null,
  atrPct: t.atrPct || tradeData.atr_pct || null,
