- PnL: ${pnl >= 0 ? '+' : ''}$${pnl.toFixed(2)}
- R final: ${rFinal >= 0 ? '+' : ''}${rFinal}R
- Cierre por: ${closeType}
- Stage al cierre: ${stage}
- Duración: ${durationTxt}
- Score AI: ${context.finalScore || 'N/A'}/100
- Scan score: ${context.scanScore || 'N/A'}
- Threshold dinámico: ${context.dynamicThreshold || 'N/A'}
- Régimen AI: ${context.aiRegime || 'N/A'}
- Bias AI: ${context.aiBias || 'N/A'}
- Setup: ${context.setupLabel || 'N/A'}
- 4H: ${context.tf4hStatus || 'N/A'}
- Macro: ${context.macroBias || 'N/A'}
- Motivo entrada: ${context.entryReason || 'N/A'}
- Vision state: ${tradeData.vision_state || 'N/A'}

INDICADORES AL ENTRAR:
- RSI: ${context.rsi14 || 'N/A'}
- Vol ratio: ${context.volRatio || 'N/A'}x
